import { z } from "zod";
import { talkHintPluginPackage } from "./plugin";
import { packagedSecretarySkills } from "./pluginWorkflow";

const configSchema = z.object({
  origin: z.string().url(),
  mode: z.enum(["read-only", "outbound"]),
  // Copy the actual .app.json generated by ChatGPT/plugin-creator; never fabricate it.
  registeredApps: z.object({ apps: z.record(z.unknown()) }).strict().optional(),
}).strict();

function inspectMapping(value: unknown, ids: string[]) {
  if (typeof value === "string" && /^plugin_asdk_app[_-][A-Za-z0-9_-]+$/.test(value)) ids.push(value);
  if (!value || typeof value !== "object") return;
  for (const [key, child] of Object.entries(value)) {
    if (/token|secret|password|api.?key|cookie|headers|authorization/i.test(key))
      throw new Error("Registered mapping must contain public connection metadata only");
    inspectMapping(child, ids);
  }
}

/** Offline source/candidate only. No registration, OAuth, HTTP or calls. */
export function preparePrivatePlugin(raw: unknown) {
  const config = configSchema.parse(raw);
  if (/\.(invalid|test|localhost|local|example)$/.test(new URL(config.origin).hostname))
    throw new Error("Private plugin requires the verified public HTTPS origin, not a review placeholder");
  const base = talkHintPluginPackage(config.origin, config.mode === "outbound");
  if (config.registeredApps) {
    if (Object.keys(config.registeredApps.apps).length !== 1)
      throw new Error("Use exactly one existing TalkHint registered MCP connection");
    const ids: string[] = [];
    inspectMapping(config.registeredApps, ids);
    if (new Set(ids).size !== 1)
      throw new Error("Copy the actual registered MCP mapping; an installed plugin ID is not a registered MCP ID");
  }
  const manifest = { ...base.manifest, extensions: { "com.openai": {
    ...base.manifest.extensions["com.openai"],
    interface: { ...base.manifest.extensions["com.openai"].interface,
      composerIcon: "./assets/icon.png", logo: "./assets/logo.png" },
    ...(config.registeredApps ? { apps: "./.app.json" } : {}),
  } } };
  return {
    manifest, mcp: base.mcp, skills: packagedSecretarySkills(config.mode === "outbound"),
    registeredApps: config.registeredApps,
    readiness: {
      privatePackage: true, mode: config.mode, sourceOrigin: config.origin,
      structurallyComplete: !!config.registeredApps,
      registeredBindingVerifiedInChatGPT: false,
      submitted: false, published: false, realCallsMade: false,
      blockers: [
        ...(!config.registeredApps ?
          ["No registered MCP mapping supplied. Have plugin-creator bind the EXISTING TalkHint MCP connection; do not install as a working tools plugin yet."] : []),
        "Refresh the registered connection and verify its URL, seven outbound tools and OAuth in actual ChatGPT.",
        "Update/reinstall the existing local plugin copy and start a new conversation; server republish does not update installed skills.",
        "Only an owner-approved explicit test may dial. A history page or an old FAILED task is not evidence.",
      ],
    },
  };
}
